ht startbar: <?= count($rebuildAudit['csv_ods']['unpaired_csv']) ?> CSV-Datei(en) ohne passende ODS.</div><?php else: ?><form method="post" class="row g-2 mt-1"><input type="hidden" name="action" value="import_rebuild_start"><input type="hidden" name="rebuild_directory" value="<?= htmlspecialchars((string) $rebuildPreview['directory'], ENT_QUOTES) ?>"><div class="col-md-8"><label class="form-label">Bestätigung</label><input class="form-control" name="rebuild_confirmation" required placeholder="IMPORT NEU AUFBAUEN"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-danger w-100"><i class="fa-solid fa-database me-1" aria-hidden="true"></i>Backup, Reset &amp; Import starten</button></div></form><?php endif; ?><?php endif; ?></div></details><?php endif; ?>
